import csv
import io
import re


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    old_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(2147483647)
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"'))
    finally:
        csv.field_size_limit(old_limit)

    def is_number(value):
        return bool(re.fullmatch(
            r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?",
            value.strip()
        ))

    has_header = False
    if records and len(records[0]) >= 2:
        first = records[0]
        later = [row for row in records[1:21] if len(row) >= 2]
        if later and not is_number(first[0]) and not is_number(first[1]):
            numeric_later = sum(
                is_number(row[0]) and is_number(row[1]) for row in later
            )
            has_header = numeric_later > len(later) / 2

    width = max([8] + [len(row) for row in records])
    if has_header:
        columns = list(records[0])
        rows = records[1:]
    else:
        columns = []
        rows = records

    columns.extend("column_{}".format(i + 1) for i in range(len(columns), width))
    rows = [row + [""] * (width - len(row)) for row in rows]
    return {"columns": columns, "rows": rows}
